#include <Arduino.h>
#include <Arduino.h>
const int SHCP = A2;    
const int STCP = A1;    
const int DS = A0;      
const byte segMap[10] = {
  0b11000000, 
  0b11111001, 
  0b10100100, 
  0b10110000, 
  0b10011001, 
  0b10010010, 
  0b10000010, 
  0b11111000, 
  0b10000000, 
  0b10010000  
};
int counter = 0;
unsigned long lastUpdate = 0;

void updateDisplay(int num);
void updateBarGraph(int tens);
void setRGB(int val);
void setup();
void loop();
void updateDisplay(int num) {
  digitalWrite(STCP, LOW);
  shiftOut(DS, SHCP, MSBFIRST, segMap[num % 10]);  
  shiftOut(DS, SHCP, MSBFIRST, segMap[num / 10]);  
  digitalWrite(STCP, HIGH);
}
void updateBarGraph(int tens) {
  for(int i = 8; i <= 13; i++) {
    digitalWrite(i, (i-8) < min(tens,8) ? HIGH : LOW);
  }
  digitalWrite(44, (8) < min(tens,8) ? HIGH : LOW);
  digitalWrite(45, (9) < min(tens,8) ? HIGH : LOW);
}
void setRGB(int val) {
  for(int p = 2; p <=7; p++) digitalWrite(p, LOW);
  if(val <= 5) {        
    digitalWrite(2, HIGH);
    digitalWrite(5, HIGH);
  } else if(val <=  9) { 
    digitalWrite(3, HIGH);
    digitalWrite(6, HIGH);
  } else {               
    digitalWrite(4, HIGH);
    digitalWrite(7, HIGH);
  }
}
void setup() {
  pinMode(SHCP, OUTPUT);
  pinMode(STCP, OUTPUT);
  pinMode(DS, OUTPUT);
  for(int i = 8; i <= 13; i++) pinMode(i, OUTPUT);
  pinMode(44, OUTPUT);
  pinMode(45, OUTPUT);
  for(int i = 2; i <=7; i++) pinMode(i, OUTPUT);
  updateDisplay(0);
  updateBarGraph(0);
  setRGB(0);
}
void loop() {
  if(millis() - lastUpdate >= 2000) {
    lastUpdate = millis();
    counter = (counter + 1) % 100;
    updateDisplay(counter);
    updateBarGraph(counter / 10);
    setRGB(counter);
  }
}
